<link rel="preload" as="font" type="font/woff2" crossorigin href="https://fonts.bunny.net/noto-sans-bengali/files/noto-sans-bengali-bengali-600-normal.woff2">
<link rel="stylesheet" href="https://fonts.bunny.net/css?family=inter:400,500,600,700|noto-sans-bengali:400,500,600,700&display=swap">
